local function connect(signal, callback)
    local connection = signal:Connect(callback)
    connections[#connections + 1] = connection
    return connection
end

local function make(className, properties, parent)
    local object = Instance.new(className)
    for key, value in pairs(properties or {}) do
        object[key] = value
    end
    object.Parent = parent
    return object
end

local function bind(object, property, token)
    bindings[#bindings + 1] = {object = object, property = property, token = token}
    object[property] = currentTheme[token]
    return object
end

local function corner(object, radius)
    return make("UICorner", {CornerRadius = UDim.new(0, radius or 10)}, object)
end

local function stroke(object, token, transparency)
    local line = make("UIStroke", {
        Thickness = 1,
        Transparency = transparency or 0,
        ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
    }, object)
    bind(line, "Color", token or "border")
    return line
end

local function pad(object, left, top, right, bottom)
    return make("UIPadding", {
        PaddingLeft = UDim.new(0, left),
        PaddingTop = UDim.new(0, top),
        PaddingRight = UDim.new(0, right or left),
        PaddingBottom = UDim.new(0, bottom or top),
    }, object)
end

local function label(parent, text, size, token, properties)
    local settings = {
        BackgroundTransparency = 1,
        Text = text,
        TextSize = size or 14,
        Font = Enum.Font.Gotham,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextYAlignment = Enum.TextYAlignment.Center,
        BorderSizePixel = 0,
        Size = UDim2.new(1, 0, 0, 22),
    }
    for key, value in pairs(properties or {}) do
        settings[key] = value
    end
    return bind(make("TextLabel", settings, parent), "TextColor3", token or "text")
end

local function tween(object, properties, duration)
    if not alive or not object.Parent then
        return
    end
    if state.reducedMotion then
        for property, value in pairs(properties) do
            object[property] = value
        end
        return
    end
    TweenService:Create(object, TweenInfo.new(duration or 0.18, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), properties):Play()
end

local function button(parent, text, properties, accent)
    local settings = {
        Text = text,
        TextSize = 12,
        Font = Enum.Font.GothamMedium,
        BorderSizePixel = 0,
        AutoButtonColor = false,
        Size = UDim2.fromOffset(110, 34),
    }
    for key, value in pairs(properties or {}) do
        settings[key] = value
    end
    local object = make("TextButton", settings, parent)
    bind(object, "BackgroundColor3", accent and "accent" or "elevated")
    bind(object, "TextColor3", accent and "contrast" or "text")
    corner(object, 8)
    connect(object.MouseEnter, function()
        tween(object, {BackgroundTransparency = 0.18}, 0.12)
    end)
    connect(object.MouseLeave, function()
        tween(object, {BackgroundTransparency = 0}, 0.12)
    end)
    return object
end

local function record(text)
    table.insert(history, 1, {time = os.date("%H:%M:%S"), text = text})
    if #history > 40 then
        table.remove(history)
    end
end

