notify = function(title, message, force)
    record(title .. ": " .. message)
    if not alive or (not state.notifications and not force) then
        return
    end
    toastSerial = toastSerial + 1
    local toast = make("Frame", {
        Size = UDim2.new(1, 0, 0, 76),
        BorderSizePixel = 0,
        LayoutOrder = toastSerial,
    }, toastHost)
    bind(toast, "BackgroundColor3", "panel")
    corner(toast, 12)
    stroke(toast, "border")
    local edge = make("Frame", {
        Position = UDim2.fromOffset(0, 14),
        Size = UDim2.fromOffset(3, 48),
        BorderSizePixel = 0,
    }, toast)
    bind(edge, "BackgroundColor3", "accent")
    corner(edge, 2)
    label(toast, title, 12, "text", {
        Position = UDim2.fromOffset(16, 12),
        Size = UDim2.new(1, -29, 0, 18),
        Font = Enum.Font.GothamMedium,
    })
    label(toast, message, 11, "muted", {
        Position = UDim2.fromOffset(16, 33),
        Size = UDim2.new(1, -29, 0, 31),
        TextWrapped = true,
        TextYAlignment = Enum.TextYAlignment.Top,
    })
    local children = {}
    for _, child in ipairs(toastHost:GetChildren()) do
        if child:IsA("Frame") then
            children[#children + 1] = child
        end
    end
    if #children > 3 then
        children[1]:Destroy()
    end
    task.delay(4, function()
        if toast.Parent then
            toast:Destroy()
        end
    end)
end

local function refreshSearch()
    local query = string.lower(searchBox.Text)
    for _, entry in ipairs(searchEntries) do
        if entry.object.Parent then
            entry.object.Visible = query == "" or string.find(entry.text, query, 1, true) ~= nil
        end
    end
end
connect(searchBox:GetPropertyChangedSignal("Text"), refreshSearch)

local function searchable(object, text)
    searchEntries[#searchEntries + 1] = {object = object, text = string.lower(text)}
end

