    bind(scroll, "ScrollBarImageColor3", "border")
    pad(scroll, 1, 1, 9, 14)
    make("UIListLayout", {Padding = UDim.new(0, 10), SortOrder = Enum.SortOrder.LayoutOrder}, scroll)
    pages[name] = {frame = scroll, subtitle = subtitle}
    local nav = button(navList, "", {
        Size = UDim2.new(1, 0, 0, 41),
        BackgroundTransparency = 1,
        LayoutOrder = #navButtons + 1,
    })
    local indicator = make("Frame", {
        Position = UDim2.fromOffset(0, 11),
        Size = UDim2.fromOffset(3, 19),
        BorderSizePixel = 0,
        Visible = false,
    }, nav)
    bind(indicator, "BackgroundColor3", "accent")
    corner(indicator, 2)
    local icon = label(nav, glyph, 15, "muted", {
        Position = UDim2.fromOffset(15, 0),
        Size = UDim2.fromOffset(25, 41),
        Font = Enum.Font.Code,
    })
    local text = label(nav, name, 12, "muted", {
        Position = UDim2.fromOffset(48, 0),
        Size = UDim2.new(1, -55, 1, 0),
        Font = Enum.Font.GothamMedium,
    })
    navButtons[#navButtons + 1] = {name = name, button = nav, text = text, icon = icon, indicator = indicator}
    connect(nav.Activated, function()
        selectPage(name)
    end)
    return scroll
end

local function refreshNavigation()
    for _, entry in ipairs(navButtons) do
        local selected = entry.name == activePage
        entry.button.BackgroundColor3 = currentTheme.elevated
        entry.button.BackgroundTransparency = selected and 0 or 1
        entry.text.TextColor3 = selected and currentTheme.text or currentTheme.muted
        entry.icon.TextColor3 = selected and currentTheme.accent or currentTheme.muted
        entry.indicator.Visible = selected
    end
end

selectPage = function(name)
    if not pages[name] then
        return
    end
    activePage = name
    for pageName, page in pairs(pages) do
        page.frame.Visible = pageName == name
    end
    pageTitle.Text = name
    breadcrumb.Text = "WORKSPACE  /  " .. string.upper(name)
    searchBox.Text = ""
    searchBox.PlaceholderText = "Search " .. string.lower(name) .. " controls..."
    refreshSearch()
    refreshNavigation()
end

