local function invoke(callback, value)
    if not callback then
        return
    end
    local success, message = pcall(callback, value)
    if not success then
        notify("Control error", tostring(message))
    end
end

local function toggle(parent, title, description, key, callback)
    local holder = row(parent, title, description)
    local track = button(holder, "", {
        Position = UDim2.new(1, -66, 0, 22),
        Size = UDim2.fromOffset(46, 25),
    })
    corner(track, 99)
    local thumb = make("Frame", {
        Size = UDim2.fromOffset(17, 17),
        Position = UDim2.fromOffset(4, 4),
        BorderSizePixel = 0,
    }, track)
    corner(thumb, 99)
    local function refresh()
        local enabled = state[key]
        track.BackgroundColor3 = enabled and currentTheme.accent or currentTheme.border
        thumb.BackgroundColor3 = enabled and currentTheme.contrast or currentTheme.muted
        tween(thumb, {Position = UDim2.fromOffset(enabled and 25 or 4, 4)}, 0.14)
    end
    local function set(value, silent)
        if type(value) ~= "boolean" then
            return
        end
        state[key] = value
        refresh()
        if not silent then
            invoke(callback, value)
        end
    end
    controls[key] = {set = set, refresh = refresh, kind = "boolean"}
    connect(track.Activated, function()
        set(not state[key])
    end)
    refresh()
    return holder
end

local function slider(parent, title, description, key, minimum, maximum, step, suffix, callback)
    local holder = row(parent, title, description, 102)
    local valueLabel = label(holder, "", 12, "accent", {
        Position = UDim2.new(1, -113, 0, 12),
        Size = UDim2.fromOffset(94, 20),
        TextXAlignment = Enum.TextXAlignment.Right,
        Font = Enum.Font.Code,
    })
    local track = make("Frame", {
        Position = UDim2.fromOffset(18, 78),
        Size = UDim2.new(1, -36, 0, 5),
        BorderSizePixel = 0,
    }, holder)
    bind(track, "BackgroundColor3", "border")
    corner(track, 99)
    local fill = make("Frame", {Size = UDim2.fromScale(0, 1), BorderSizePixel = 0}, track)
    bind(fill, "BackgroundColor3", "accent")
    corner(fill, 99)
    local thumb = make("Frame", {
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.fromScale(0, 0.5),
        Size = UDim2.fromOffset(13, 13),
        BorderSizePixel = 0,
    }, track)
    bind(thumb, "BackgroundColor3", "text")
    corner(thumb, 99)
    local hit = make("TextButton", {
        Position = UDim2.new(0, 0, 0.5, -14),
        Size = UDim2.new(1, 0, 0, 28),
        BackgroundTransparency = 1,
        Text = "",
    }, track)
    local dragging = nil
    local function refresh()
        local ratio = (state[key] - minimum) / (maximum - minimum)
        fill.Size = UDim2.fromScale(ratio, 1)
        thumb.Position = UDim2.fromScale(ratio, 0.5)
        local value = math.floor(state[key] * 100 + 0.5) / 100
        valueLabel.Text = tostring(value) .. (suffix or "")
    end
    local function set(value, silent)
        if type(value) ~= "number" or value ~= value or math.abs(value) == math.huge then
            return
        end
        local snapped = minimum + math.floor((value - minimum) / step + 0.5) * step
        state[key] = math.clamp(snapped, minimum, maximum)
        refresh()
        if not silent then
            invoke(callback, state[key])
        end
    end
    local function update(input)
        local width = track.AbsoluteSize.X
        if width <= 0 then
            return
        end
        local ratio = math.clamp((input.Position.X - track.AbsolutePosition.X) / width, 0, 1)
        set(minimum + ratio * (maximum - minimum))
    end
    connect(hit.InputBegan, function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = input
            update(input)
        end
    end)
    connect(UserInputService.InputChanged, function(input)
        if dragging and (input == dragging or input.UserInputType == Enum.UserInputType.MouseMovement) then
            update(input)
        end
    end)
    connect(UserInputService.InputEnded, function(input)
        if input == dragging or input.UserInputType == Enum.UserInputType.MouseButton1 then
            dragging = nil
        end
    end)
    controls[key] = {set = set, refresh = refresh, kind = "number"}
    refresh()
    return holder
end

