local function choice(parent, title, description, key, options, callback)
    local holder = row(parent, title, description)
    local control = button(holder, "", {
        Position = UDim2.new(1, -162, 0, 18),
        Size = UDim2.fromOffset(144, 33),
    })
    local function refresh()
        control.Text = tostring(state[key]) .. "  >"
    end
    local function set(value, silent)
        if not table.find(options, value) then
            return
        end
        state[key] = value
        refresh()
        if not silent then
            invoke(callback, value)
        end
    end
    connect(control.Activated, function()
        local index = table.find(options, state[key]) or 1
        set(options[index % #options + 1])
    end)
    controls[key] = {set = set, refresh = refresh, kind = "string"}
    refresh()
    return holder
end

local function textInput(parent, title, placeholder, height)
    local holder = make("Frame", {
