local function humanoid()
    local character = player.Character
    return character and character:FindFirstChildOfClass("Humanoid")
end

local function rememberHumanoid(value)
    if value and not originalHumanoids[value] then
        originalHumanoids[value] = {
            WalkSpeed = value.WalkSpeed,
            JumpPower = value.JumpPower,
            JumpHeight = value.JumpHeight,
        }
    end
end

local function applyMovement()
    local value = humanoid()
    if not value then
        return
    end
    rememberHumanoid(value)
    local original = originalHumanoids[value]
    if state.movement then
        value.WalkSpeed = state.walkSpeed
        if value.UseJumpPower then
            value.JumpPower = state.jumpPower
        else
            value.JumpHeight = state.jumpPower ^ 2 / (2 * math.max(workspace.Gravity, 1))
        end
    else
        value.WalkSpeed = original.WalkSpeed
        value.JumpPower = original.JumpPower
        value.JumpHeight = original.JumpHeight
    end
end

