local configBox = textInput(settingsPage, "Configuration JSON", "Export a configuration, or paste one here to import.", 200)
local function exportConfig()
    local values = {}
    for key in pairs(controls) do
        values[key] = state[key]
    end
    configBox.Text = HttpService:JSONEncode({version = 1, values = values, notes = notes.Text})
    notify("Configuration exported", "Select and copy the JSON from the text field.")
end
local function importConfig()
    local success, result = pcall(function()
        return HttpService:JSONDecode(configBox.Text)
    end)
    if not success or type(result) ~= "table" or result.version ~= 1 or type(result.values) ~= "table" then
        notify("Invalid configuration", "Paste an ORBIT version 1 JSON export.")
        return
    end
    local applied = 0
    for key, control in pairs(controls) do
        local value = result.values[key]
        if type(value) == control.kind then
            control.set(value, true)
            applied = applied + 1
        end
    end
    if type(result.notes) == "string" then
        notes.Text = string.sub(result.notes, 1, 10000)
    end
    applyTheme()
    applyMovement()
    applyCamera()
    applyLighting()
    updateCrosshair()
    hud.Visible = state.showStats
    coordinatesHud.Visible = state.showCoordinates
    resize()
    notify("Configuration imported", tostring(applied) .. " recognized settings processed.", true)
end
action(settingsPage, "Export configuration", "Write your current settings into the JSON field.", "Export JSON", exportConfig, true)
action(settingsPage, "Import configuration", "Apply the recognized settings from the JSON field.", "Import JSON", importConfig)
