end)
section(settingsPage, "Session lifecycle")

local function cleanup()
    if not alive then
        return
    end
    alive = false
    for _, connection in ipairs(connections) do
        connection:Disconnect()
    end
    table.clear(connections)
    for _, callback in ipairs(cleanups) do
        pcall(callback)
    end
    for value, original in pairs(originalHumanoids) do
        if value.Parent then
            pcall(function()
                value.WalkSpeed = original.WalkSpeed
                value.JumpPower = original.JumpPower
                value.JumpHeight = original.JumpHeight
            end)
        end
    end
    for camera, fov in pairs(originalCameras) do
        if camera.Parent then
            pcall(function()
                camera.FieldOfView = fov
            end)
        end
    end
    if state.customLighting then
        for property, value in pairs(originalLighting) do
            pcall(function()
                Lighting[property] = value
            end)
        end
    end
    if screen.Parent then
        screen:Destroy()
    end
end

action(settingsPage, "Unload ORBIT", "Restore modified values and disconnect every listener.", "Unload hub", cleanup)
