connect(UserInputService.InputBegan, function(input, processed)
    if processed or UserInputService:GetFocusedTextBox() then
        return
    end
    if input.KeyCode == Enum.KeyCode.RightShift then
        setVisible(not window.Visible)
    elseif input.KeyCode == Enum.KeyCode.Escape and window.Visible then
        setVisible(false)
    end
end)

local dragInput = nil
local dragStart = nil
local startPosition = nil
connect(topbar.InputBegan, function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
        dragInput = input
        dragStart = input.Position
        startPosition = window.Position
    end
end)
connect(UserInputService.InputChanged, function(input)
    if not dragInput or not dragStart or not startPosition then
        return
    end
    if input ~= dragInput and input.UserInputType ~= Enum.UserInputType.MouseMovement then
        return
    end
    local delta = input.Position - dragStart
    local viewport = overlay.AbsoluteSize
    local width = window.AbsoluteSize.X
    local height = window.AbsoluteSize.Y
    local centerX = startPosition.X.Scale * viewport.X + startPosition.X.Offset + delta.X
    local centerY = startPosition.Y.Scale * viewport.Y + startPosition.Y.Offset + delta.Y
    centerX = math.clamp(centerX, width / 2, math.max(width / 2, viewport.X - width / 2))
    centerY = math.clamp(centerY, height / 2, math.max(height / 2, viewport.Y - height / 2))
    window.Position = UDim2.fromOffset(centerX, centerY)
end)
connect(UserInputService.InputEnded, function(input)
    if input == dragInput or input.UserInputType == Enum.UserInputType.MouseButton1 then
        dragInput = nil
        dragStart = nil
        startPosition = nil
    end
end)

