local function duration(seconds, tenths)
    local minutes = math.floor(seconds / 60)
    local remainder = math.floor(seconds % 60)
    if tenths then
        return string.format("%02d:%02d.%d", minutes, remainder, math.floor(seconds * 10) % 10)
    end
    return string.format("%02d:%02d", minutes, remainder)
end

local function updateReadouts()
    local runningFor = os.clock() - startedAt
    fpsMetric.Text = tostring(measuredFps) .. " FPS"
    timeMetric.Text = duration(runningFor)
    hudText.Text = string.format("ORBIT  /  %d FPS  /  %s", measuredFps, duration(runningFor))
    local timer = stopwatchElapsed + (stopwatchStarted and os.clock() - stopwatchStarted or 0)
    timerLabel.Text = duration(timer, true)
    local character = player.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    local value = humanoid()
    local labels = {}
    for _, child in ipairs(characterReadout:GetChildren()) do
        if child:IsA("TextLabel") and child ~= healthLabel then
            labels[#labels + 1] = child
        end
    end
    if value then
        healthLabel.Text = string.format("%d / %d HP", math.ceil(value.Health), math.ceil(value.MaxHealth))
        healthFill.Size = UDim2.fromScale(math.clamp(value.Health / math.max(value.MaxHealth, 1), 0, 1), 1)
        if labels[1] then
            labels[1].Text = value.RigType.Name .. " character"
        end
        if labels[2] then
            labels[2].Text = "State: " .. value:GetState().Name
        end
    else
        healthLabel.Text = "-- / -- HP"
        healthFill.Size = UDim2.fromScale(0, 1)
        if labels[1] then
            labels[1].Text = "Waiting for character"
        end
    end
    if root then
        local position = root.Position
        local text = string.format("X %.1f  Y %.1f  Z %.1f", position.X, position.Y, position.Z)
        coordinatesLabel.Text = text
        coordinatesHud.Text = text
    else
        coordinatesLabel.Text = "Waiting for character"
        coordinatesHud.Text = "Waiting for character"
    end
end

connect(RunService.RenderStepped, function(deltaTime)
    frameCount = frameCount + 1
    elapsed = elapsed + deltaTime
    if elapsed >= 0.25 then
        measuredFps = math.floor(frameCount / elapsed + 0.5)
        frameCount = 0
        elapsed = 0
        updateReadouts()
    end
end)

rememberHumanoid(humanoid())
watchCamera()
updateCrosshair()
selectPage("Overview")
applyTheme()
updateReadouts()
notify("Welcome to ORBIT", "Right Shift hides the hub. Your session is ready.")

]]

